        "titolo_orig": "Hanoi cambia volto",
        "testo_it": "Hanoi si prepara a un'estate di caldo estremo, con temperature che superano i 40 gradi già a fine maggio.",
        "priorita": "Bassa",
        "id_gruppo": 24,
        "link": "https://www.internazionale.it/notizie/junko-terao/2026/06/02/hanoi-cambia-volto",
